package com.yeyamo_mobile.api.booking_service.infrastructure.persistence;import java.util.*;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import jakarta.persistence.LockModeType;
public interface BookingRepository extends JpaRepository<BookingEntity,UUID>{List<BookingEntity>findByUserIdOrderByCreatedAtDesc(String user);Optional<BookingEntity>findByReference(String reference);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select b from BookingEntity b where b.id=:id")Optional<BookingEntity>findLocked(@Param("id")UUID id);}
